function uid(prefix="item"){return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,8)}`}
function clone(value){return JSON.parse(JSON.stringify(value))}
function svgIcon(id){return `<svg aria-hidden="true"><use href="#${id}"/></svg>`}
function project(){return Array.isArray(state.projects)?(state.projects.find(p=>p&&p.id===state.activeProject)||null):null}
const COLLAB_ROLE_LABEL={view:"Просмотр",comment:"Комментарии",edit:"Редактирование"};
function ensureSharing(){const p=project();if(!p)return null;if(!p.sharing||typeof p.sharing!=="object")p.sharing={visibility:"invite",linkRole:"view",token:uid("share"),members:[]};if(!Array.isArray(p.sharing.members))p.sharing.members=[];if(!p.sharing.token)p.sharing.token=uid("share");return p.sharing}
function collabDescriptor(){const sh=ensureSharing();return sh&&project()?`osminog://project/${encodeURIComponent(project().id)}?access=${encodeURIComponent(sh.token)}&role=${encodeURIComponent(sh.linkRole||"view")}`:""}
function initials(value){const v=String(value||"?").trim();return(v.split(/\s+/).slice(0,2).map(x=>x[0]||"").join("")||"?").toUpperCase().slice(0,2)}
