  if(obj.type==="shape")return `<div class="object-content"></div>`;
  if(obj.type==="vector")return `<div class="object-content vector-content"><svg class="vector-object-svg" viewBox="0 0 ${Math.max(1,obj.w)} ${Math.max(1,obj.h)}" preserveAspectRatio="none"><defs>${vectorGradientDef(obj)}</defs><path class="vector-hit-path" d="${vectorPathD(obj)}" fill="none" stroke="transparent" stroke-width="18"></path><path class="vector-object-path" d="${vectorPathD(obj)}" fill="${vectorFillValue(obj)}" stroke="${obj.strokeEnabled===false?"none":(obj.stroke||"none")}" stroke-width="${obj.strokeWidth||0}"></path></svg>${vectorNodeOverlay(obj)}</div>`;
  if(obj.type==="button")return `<div class="object-content button-content"><button class="prototype-button" type="button">${esc(obj.label||obj.name)}</button></div>`;
  if(obj.type==="ink")return `<div class="object-content"><svg class="ink-object-svg" viewBox="0 0 1000 1000" preserveAspectRatio="none"><path class="ink-path" d="${inkPathD(obj)}" style="stroke:${obj.stroke||"#20252e"};stroke-width:${Math.max(1,(obj.strokeWidth||3)*1000/Math.max(obj.w,obj.h))}"></path></svg></div>`
  if(obj.type==="image")return `<div class="object-content image-raw"><img src="${obj.src}" alt="${esc(obj.name)}"></div>`;
  if(obj.type==="file")return obj.mime==="application/pdf"&&obj.fileExpanded?`${objectBar(obj)}${pdfFileHtml(obj)}`:`<div class="object-content compact-file-content">${bcFileIconMarkup(obj)}</div>`;
  if(obj.type==="code")return `${objectBar(obj,`<button class="code-view-toggle" type="button">${obj.codeViewMode==="preview"?"Код + preview":"Только visual"}</button><button class="code-run">${tr("run")}</button>`)}<div class="object-content code-layout ${obj.codeViewMode==="preview"?"preview-only":""}" style="--code-split:${Math.max(18,Math.min(82,Number(obj.codeSplit)||50))}%"><textarea spellcheck="false">${esc(obj.code)}</textarea><div class="code-splitter" title="Потяни границу"></div><iframe sandbox="allow-scripts"></iframe></div>`;
