  const gridFields=`<div class="field full"><label>${tr("grid")}</label><select id="gridStyle"><option value="plain" ${c.grid==="plain"?"selected":""}>${tr("plain")}</option><option value="dots" ${c.grid==="dots"?"selected":""}>${tr("dots")}</option><option value="grid" ${c.grid==="grid"?"selected":""}>${tr("gridOnly")}</option><option value="both" ${c.grid==="both"?"selected":""}>${tr("dotsGrid")}</option></select></div>${c.grid!=="plain"?`<div class="field full"><label>${tr("gridSize")}</label><input id="gridSize" type="number" min="8" max="160" value="${c.size}"></div>`:""}`;
