function xml(value){return esc(value).replace(/'/g,"&apos;")}
function exportSvgText(){
  const list=exportObjects();
  if(!list.length)return `<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="800"/>`;
  const minX=Math.min(...list.map(o=>o.x))-30,minY=Math.min(...list.map(o=>o.y))-30;
  const maxX=Math.max(...list.map(o=>o.x+o.w))+30,maxY=Math.max(...list.map(o=>o.y+o.h))+30;
  const w=maxX-minX,h=maxY-minY;
  const links=project().connections.map((c,index)=>{
    const a=list.find(o=>o.id===c.from),b=list.find(o=>o.id===c.to);
    if(!a||!b)return"";
    const x1=a.x+a.w-minX,y1=a.y+a.h/2-minY,x2=b.x-minX,y2=b.y+b.h/2-minY;
    const style=c.style||"curve";
    const d=style==="straight"
      ?`M${x1} ${y1} L${x2} ${y2}`
      :style==="elbow"
        ?`M${x1} ${y1} L${(x1+x2)/2} ${y1} L${(x1+x2)/2} ${y2} L${x2} ${y2}`
        :`M${x1} ${y1} C${x1+Math.max(56,Math.abs(x2-x1)*.35)} ${y1},${x2-Math.max(56,Math.abs(x2-x1)*.35)} ${y2},${x2} ${y2}`;
    const color=c.color||"#365dfb",markerId=`arrow-${index}`;
    const label=xml(c.label||c.description||"");
    const mx=(x1+x2)/2,my=(y1+y2)/2;
    return `${c.arrow!==false?`<marker id="${markerId}" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8 Z" fill="${color}"/></marker>`:""}<path d="${d}" fill="none" stroke="${color}" stroke-width="${c.width||3}" ${c.dashed?`stroke-dasharray="10 8"`:""} ${c.arrow!==false?`marker-end="url(#${markerId})"`:""}/>${label?`<text x="${mx}" y="${my-10}" text-anchor="middle" font-family="Arial" font-size="12" fill="${color}">${label}</text>`:""}`;
  }).join("");
  const cards=list.map(o=>{
    const x=o.x-minX,y=o.y-minY,fill=o.fill&&o.fill!=="transparent"?o.fill:"#ffffff",stroke=o.stroke||"#d9dde7";
    if(o.type==="image"&&o.src)return `<g opacity="${o.opacity??1}"><rect x="${x}" y="${y}" width="${o.w}" height="${o.h}" rx="${o.radius||0}" fill="${fill}" stroke="${stroke}"/><image href="${o.src}" x="${x+8}" y="${y+8}" width="${o.w-16}" height="${o.h-16}" preserveAspectRatio="xMidYMid meet"/></g>`;
    const lines=objectText(o).split(/\n/).flatMap(s=>{const words=s.split(/\s+/),out=[];let line="";words.forEach(word=>{if((line+" "+word).length>Math.max(18,Math.floor(o.w/10))){out.push(line);line=word}else line+=(line?" ":"")+word});if(line)out.push(line);return out}).slice(0,Math.max(2,Math.floor((o.h-52)/22)));
    return `<g opacity="${o.opacity??1}" transform="rotate(${o.rotation||0} ${x+o.w/2} ${y+o.h/2})"><rect x="${x}" y="${y}" width="${o.w}" height="${o.h}" rx="${o.radius||0}" fill="${fill}" stroke="${stroke}" stroke-width="${o.strokeWidth||1}"/><text x="${x+20}" y="${y+30}" font-family="Arial" font-size="11" fill="#677083">${xml(o.name)}</text>${lines.map((line,i)=>`<text x="${x+20}" y="${y+62+i*22}" font-family="Arial" font-size="16" fill="#1b2435">${xml(line)}</text>`).join("")}</g>`;
  }).join("");
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${Math.ceil(w)}" height="${Math.ceil(h)}" viewBox="0 0 ${w} ${h}"><rect width="100%" height="100%" fill="${state.theme==="ocean"?"#052e54":state.theme!=="light"?"#16181b":"#f6f7f8"}"/>${links}${cards}</svg>`;
}
