  function fileIcon(obj){const k=kindOf(obj),label=bcFileShortLabel?.(obj)||extOf(obj).toUpperCase()||"FILE";if(k==="image"&&obj.src)return`<img src="${esc(obj.src)}" alt="">`;return`<span class="bc-gallery-file-icon bc-kind-${k}">${esc(label)}</span>`}

