/* Microfix 3.8.42: prevent native image drag duplication + Figma-like keyboard nudging */
(()=>{
  const viewport=document.getElementById("viewport");
  const isEditableTarget=target=>target instanceof Element&&!!target.closest("input,textarea,[contenteditable]");
  const isCanvasImage=target=>target instanceof Element&&!!target.closest(".canvas-object.image-object img,.canvas-object .image-raw img,.files-gallery img,.project-preview img");
  const disableNativeImageDrag=root=>root?.querySelectorAll?.(".canvas-object img,.files-gallery img,.project-preview img").forEach(img=>{img.draggable=false;img.setAttribute("draggable","false")});
  disableNativeImageDrag(document);
  const observeRoot=document.getElementById("app")||document.body;
  if(observeRoot)new MutationObserver(records=>{for(const record of records)for(const node of record.addedNodes)if(node instanceof Element){if(node.matches?.("img")){node.draggable=false;node.setAttribute("draggable","false")}disableNativeImageDrag(node)}}).observe(observeRoot,{childList:true,subtree:true});
  document.addEventListener("dragstart",event=>{if(isCanvasImage(event.target)&&!event.target.closest?.(".ai-context-handle")){event.preventDefault();event.stopImmediatePropagation()}},true);
  viewport?.addEventListener("drop",event=>{const files=[...(event.dataTransfer?.files||[])];if(!files.length){event.preventDefault();event.stopImmediatePropagation()}},true);

  let nudgeSession=false,nudgeTimer=0;
  document.addEventListener("keydown",event=>{
    if(document.getElementById("app")?.hidden||!["ArrowLeft","ArrowRight","ArrowUp","ArrowDown"].includes(event.key)||isEditableTarget(event.target))return;
    if(!Array.isArray(state.selected)||!state.selected.length||state.selectedConnection||state.nodeDrag||state.vectorAnchorDrag||state.connect)return;
    event.preventDefault();event.stopImmediatePropagation();
    if(!nudgeSession){checkpoint();nudgeSession=true}
    const step=event.shiftKey?10:1,dx=event.key==="ArrowLeft"?-step:event.key==="ArrowRight"?step:0,dy=event.key==="ArrowUp"?-step:event.key==="ArrowDown"?step:0;
    selectedObjects().forEach(obj=>{obj.x=(Number(obj.x)||0)+dx;obj.y=(Number(obj.y)||0)+dy});
    renderObjects();renderConnections();renderLayers();renderInspector();queuePersist();
    clearTimeout(nudgeTimer);nudgeTimer=setTimeout(()=>{nudgeSession=false},240);
  },true);
})();

